import pandas as pd

df = pd.read_excel('/app/.hermes/cache/documents/doc_62a60f9d8630_CID title.xlsx', sheet_name='人群画像', header=None)

# 用正确的方式解析层级结构
current_cat = ""
current_subcat = ""
results = []

for i in range(len(df)):
    row = df.iloc[i]
    c1, c3, c5 = row[1], row[3], row[5]
    c6, c7 = row[6], row[7]

    c1 = str(c1).strip() if pd.notna(c1) else ""
    c3 = str(c3).strip() if pd.notna(c3) else ""
    c5 = str(c5).strip() if pd.notna(c5) else ""

    has_data = pd.notna(c6) and c6 != ""

    if c1 and c1 not in ["nan", "定义\n\n标签"]:
        current_cat = c1
        current_subcat = ""
    if c3 and c3 not in ["nan"]:
        current_subcat = c3

    if c5 and c5 not in ["nan", "ONE ID"] and current_cat:
        results.append({
            '一级分类': current_cat,
            '二级分类': current_subcat if current_subcat else "",
            '标签值': c5,
            'ONE_ID': int(c6) if has_data else 0,
            'RATIO': float(c7) if has_data else 0
        })

# 按一级分类整理
import json
cats = {}
for r in results:
    cat = r['一级分类']
    if cat not in cats:
        cats[cat] = []
    cats[cat].append(r)

# 输出
for cat, items in cats.items():
    print(f"\n{'='*70}")
    print(f"【{cat}】")
    print(f"{'='*70}")

    # 按二级分类分组
    subcats = {}
    others = []
    for item in items:
        if item['二级分类']:
            sc = item['二级分类']
            if sc not in subcats:
                subcats[sc] = []
            subcats[sc].append(item)
        else:
            others.append(item)

    for sc, sc_items in subcats.items():
        print(f"\n  [{sc}]")
        for item in sc_items:
            n = item['ONE_ID']
            ratio = item['RATIO']
            print(f"    • {item['标签值']} (N={n:,} | {ratio:.2%})" if n else f"    • {item['标签值']}")

    if others:
        print(f"\n  [直接指标]")
        for item in others:
            n = item['ONE_ID']
            ratio = item['RATIO']
            print(f"    • {item['标签值']} (N={n:,} | {ratio:.2%})" if n else f"    • {item['标签值']}")

print(f"\n\n总计: {len(results)} 个标签值")
"}
